    except Exception as e:  # noqa: BLE001
        notes.append(f"{path}: unreadable ({e})")
        return 0.0
    rows = [r for r in rows if any(c.strip() for c in r)]
    if not rows:
        notes.append("empty csv")
        return 0.0
    head = [norm(c) for c in rows[0]]
    cols = SPEC["columns"]
    if head != [norm(c) for c in cols]:
